external int flb_tostring(
  ffi.Pointer<flb_state> state,
  ffi.Pointer<flb_value> value,
  ffi.Pointer<ffi.Pointer<flb_value>> out,
);

/// A static name for a value type, for example "table".
@ffi.Native<ffi.Pointer<ffi.Char> Function(ffi.Int32)>()
external ffi.Pointer<ffi.Char> flb_type_name(int type);

/// Inside a host call: instead of returning, suspends the coroutine that
/// called the host function, and the flb_resume that runs it returns
/// FLB_YIELD with `values`. The coroutine is suspended only after the host
/// callback has returned, so no host stack frame is ever unwound. When it is
/// resumed again, the resume arguments become the results of the host
/// function; with flb_resume_failure, the host function raises instead.
///
/// Only a coroutine run by flb_resume with FLB_RESUME_HOST_YIELD can be
/// suspended, and only from its own code: not from a coroutine that Lua
/// resumed, nor through a host function that called back into Lua. Otherwise
/// the host function raises a Lua error. flb_can_yield tells in advance.
@ffi.Native<
  ffi.Int32 Function(ffi.Pointer<flb_state>, ffi.Pointer<flb_value>, ffi.Size)
>()
external int flb_yield(
  ffi.Pointer<flb_state> state,
  ffi.Pointer<flb_value> values,
  int count,
);

const int FLB_ABI_VERSION = 2;

const int FLB_BOOLEAN = 1;

const int FLB_CALL_BY_VALUE = 1;

const int FLB_ERROR_ARGUMENT = 100;

const int FLB_ERROR_CLOSED = 101;

const int FLB_ERROR_HANDLER = 5;

const int FLB_ERROR_HOST = 103;

const int FLB_ERROR_INTERRUPTED = 102;

const int FLB_ERROR_MEMORY = 4;

const int FLB_ERROR_RUNTIME = 2;

const int FLB_ERROR_SYNTAX = 3;

const int FLB_FUNCTION = 6;

const int FLB_FUNCTION_BY_VALUE = 1;

const int FLB_GC_COLLECT = 0;

const int FLB_GC_RESTART = 2;

const int FLB_GC_STEP = 3;

const int FLB_GC_STOP = 1;

const int FLB_INTEGER = 2;

const int FLB_LIBS_ALL = 2047;

const int FLB_LIBS_SAFE = 127;

const int FLB_LIB_BASE = 1;

const int FLB_LIB_COROUTINE = 2;

const int FLB_LIB_DEBUG = 512;

const int FLB_LIB_IO = 128;

const int FLB_LIB_MATH = 16;

const int FLB_LIB_OS = 256;

const int FLB_LIB_PACKAGE = 1024;

const int FLB_LIB_REQUIRE = 64;

const int FLB_LIB_STRING = 8;

const int FLB_LIB_TABLE = 4;

const int FLB_LIB_UTF8 = 32;

const int FLB_LIGHTUSERDATA = 9;

const int FLB_MODE_BINARY = 2;

const int FLB_MODE_TEXT = 1;

const int FLB_NIL = 0;

const int FLB_NUMBER = 3;

const int FLB_OK = 0;

const int FLB_RESUME_HOST_YIELD = 2;

const int FLB_STRING = 4;

const int FLB_TABLE = 5;

const int FLB_TABLE_VALUE = 10;

const int FLB_THREAD = 8;

const int FLB_THREAD_DEAD = 3;

const int FLB_THREAD_NORMAL = 2;

const int FLB_THREAD_RUNNING = 1;

const int FLB_THREAD_SUSPENDED = 0;

const int FLB_USERDATA = 7;

const int FLB_YIELD = 1;

/// Called when Lua calls a host function created with flb_function_new.
///
/// The host reads `arguments`, then reports the outcome by calling exactly one
/// of flb_return or flb_fail before returning. Returning without calling
/// either means "no results". The host may call other flb functions on
/// `state` while inside the callback.
typedef flb_host_call = ffi.Pointer<ffi.NativeFunction<flb_host_callFunction>>;
typedef flb_host_callFunction = ffi.Void Function(
  ffi.Pointer<flb_state> state,
  ffi.Int64 function_id,
  ffi.Pointer<flb_value> arguments,
  ffi.Size count,
);
typedef Dartflb_host_callFunction = void Function(
  ffi.Pointer<flb_state> state,
  int function_id,
  ffi.Pointer<flb_value> arguments,
  int count,
);

/// Called when Lua no longer references a host function (function id) or a
/// host object (object id). `is_object` tells which. Must not call back into
/// flb. Not called for a state released through flb_state_release from a
/// finalizer; the host drops everything belonging to that state itself.
typedef flb_host_release =
    ffi.Pointer<ffi.NativeFunction<flb_host_releaseFunction>>;
typedef flb_host_releaseFunction = ffi.Void Function(
  ffi.Pointer<flb_state> state,
  ffi.Int64 id,
  ffi.Int32 is_object,
);
typedef Dartflb_host_releaseFunction = void Function(
  ffi.Pointer<flb_state> state,
  int id,
  int is_object,
);

final class flb_options extends ffi.Struct {
  /// FLB_LIB_* mask
  @ffi.Uint32()
  external int libraries;

  /// bytes, 0 for no limit
  @ffi.Size()
  external int memory_limit;

  /// may be NULL if no host function is created
  external flb_host_call call;

  /// may be NULL
  external flb_host_release release;

  static ffi.Pointer<flb_options> $allocate(
    ffi.Allocator $allocator, {
    required int libraries,
    required int memory_limit,
    required flb_host_call call,
    required flb_host_release release,
  }) => $allocator<flb_options>()
    ..ref.libraries = libraries
    ..ref.memory_limit = memory_limit
    ..ref.call = call
    ..ref.release = release;
}

/// A host-owned reference to a Lua value. 0 is never a valid reference.
typedef flb_ref = ffi.Int64;
typedef Dartflb_ref = int;

final class flb_state extends ffi.Opaque {}

/// A Lua value.
///
/// type                 fields used
/// FLB_NIL             -
/// FLB_BOOLEAN         i (0 or 1)
/// FLB_INTEGER         i
/// FLB_NUMBER          n
/// FLB_STRING          bytes, length (not NUL terminated; any bytes)
/// FLB_TABLE           i (flb_ref)
/// FLB_FUNCTION        i (flb_ref)
/// FLB_USERDATA        i (flb_ref), id (host object id, 0 if not a host object)
/// FLB_THREAD          i (flb_ref)
/// FLB_LIGHTUSERDATA   i (the pointer value)
/// FLB_TABLE_VALUE     items, length (number of key/value pairs; items holds
/// key0, value0, key1, value1, ...)
///
/// When the host passes a value in, string bytes are copied and references are
/// borrowed (the host keeps ownership). When the host receives a value,
/// references in it are new and owned by the host.
///
/// Every function that takes values accepts FLB_TABLE_VALUE and builds a new
/// Lua table from it (nested up to 64 levels). The host receives
/// FLB_TABLE_VALUE only from flb_copy and in the arguments of a host function
/// created with FLB_FUNCTION_BY_VALUE.
final class flb_value extends ffi.Struct {
  @ffi.Int32()
  external int type;

  @ffi.Int64()
  external int i;

  @ffi.Double()
  external double n;

  external ffi.Pointer<ffi.Char> bytes;

  @ffi.Size()
  external int length;

  @ffi.Int64()
  external int id;

  external ffi.Pointer<flb_value> items;

  static ffi.Pointer<flb_value> $allocate(
    ffi.Allocator $allocator, {
    required int type,
    required int i,
    required double n,
    required ffi.Pointer<ffi.Char> bytes,
    required int length,
    required int id,
    required ffi.Pointer<flb_value> items,
  }) => $allocator<flb_value>()
    ..ref.type = type
    ..ref.i = i
    ..ref.n = n
    ..ref.bytes = bytes
    ..ref.length = length
    ..ref.id = id
    ..ref.items = items;
}
